using System;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.CompilerServices;
class Compatibility {
 [STAThread] static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string p=Path.Combine(root,new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};var sdk=Assembly.LoadFrom(Path.Combine(root,"AGS.Types.dll"));var editor=Assembly.LoadFrom(Path.Combine(root,"AGSEditor.exe"));Console.WriteLine("AGS "+System.Diagnostics.FileVersionInfo.GetVersionInfo(editor.Location).FileVersion+"; SDK "+sdk.FullName);
 var gui=editor.GetType("AGS.Editor.GUIController",true);Require(gui.GetMethod("GetScriptEditorControl",new[]{typeof(string),typeof(bool)})!=null,"live script access");Require(gui.GetMethod("SetPropertyGridObject",new[]{typeof(object)})!=null,"property navigation");Require(gui.GetMethod("SelectPropertyByName",new[]{typeof(string)})!=null,"property selection");var app=editor.GetType("AGS.Editor.AGSEditor",true);Require(app.GetProperty("Instance",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static)!=null,"editor singleton");Require(app.GetMethod("SaveGameFiles",Type.EmptyTypes)!=null,"project saving");var scintilla=editor.GetTypes().First(t=>t.Name=="ScintillaWrapper");Require(scintilla.GetMethod("ModifyText",new[]{typeof(string)})!=null,"native script replacement");
 var plugin=Assembly.LoadFrom(Path.GetFullPath(args[1]));int count=0;foreach(var t in plugin.GetTypes())foreach(var method in t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance|BindingFlags.DeclaredOnly)){if(!method.IsAbstract&&!method.ContainsGenericParameters){RuntimeHelpers.PrepareMethod(method.MethodHandle);count++;}}Console.WriteLine("PASS same plugin binary JIT: "+count+" methods");using(var stream=plugin.GetManifestResourceStream("AGSSpellchecker.Icon"))using(var icon=new System.Drawing.Icon(stream))Console.WriteLine("PASS embedded icon");var bridge=Activator.CreateInstance(plugin.GetType("AGSSpellchecker.EditorBridge"),new object[]{null});using(var panel=(System.Windows.Forms.Control)Activator.CreateInstance(plugin.GetType("AGSSpellchecker.ReviewPanel"),bridge)){panel.Size=new System.Drawing.Size(1000,700);panel.CreateControl();Console.WriteLine("PASS native panel construction");}return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
 static void Require(bool value,string message){if(!value)throw new Exception("Missing "+message);Console.WriteLine("PASS "+message);}
}
